315. /// Module-level singleton storage.
316. static mut INSTANCE: MaybeUninit<Inner> = MaybeUninit::uninit();
317. 
318. /// Whether the frame allocator has been initialized.
319. static INSTANCE_INIT: AtomicBool = AtomicBool::new(false);
320. 
321. /// Returns a mutable reference to the initialized singleton.
322. fn instance() -> &'static mut Inner {
323.     if unlikely(!INSTANCE_INIT.load(ORDER)) {
324.         panic!("frame allocator used before init()");
325.     }
326. 
327.     // SAFETY: `INSTANCE_INIT` is `true`, so `INSTANCE` has been fully written by `init()`.
328.     // The kernel is single-threaded with interrupts disabled, so no concurrent access is possible.
329.     unsafe { INSTANCE.assume_init_mut() }
330. }
331. 
