336. /// Initialize the frame allocator singleton.
337. ///
338. /// # Safety
339. ///
340. /// Must be called exactly once during boot, before any other function
341. /// in this module.
342. pub(super) unsafe fn init(bitmap: SparseBitmap) -> Result<(), Error> {
343.     if unlikely(INSTANCE_INIT.load(ORDER)) {
344.         return Err(Error::new(ErrorCode::InvalidArgument, "frame allocator already initialized"));
345.     }
346. 
347.     info!(
348.         "frame allocator: {} frames, {} MB, {} chunk(s)",
349.         bitmap.capacity(),
350.         (bitmap.capacity() * mem::FRAME_SIZE) / constants::MEGABYTE,
351.         bitmap.chunk_count(),
352.     );
353. 
354.     // SAFETY: single-threaded boot; no other reference to `INSTANCE` exists.
355.     unsafe { INSTANCE.write(Inner { bitmap }) };
356.     INSTANCE_INIT.store(true, ORDER);
357.     Ok(())
358. }
359. 
360. /// Allocate a frame.
361. #[verus_spec(result =>
362.     ensures
363.         match result {
364.             Ok(frame) => frame.inv(),
365.             Err(_) => true,
366.         },
367. )]
368. pub(super) fn alloc() -> Result<FrameAddress, Error> {
369.     instance().alloc()
370. }
371. 
