373. // and the attribute-based syntax does not support `no_unwind`.
374. verus! {
375. /// Free a frame previously returned by [`alloc`].
376. pub(super) fn free(frame: FrameAddress) -> (result: Result<(), Error>)
377.     opens_invariants none
